export type ParsedApiResult<T extends { ok: boolean }> = {
  responseOk: boolean;
  data: T | ApiErrorResponse;
};

type StudioGetCacheEntry = {
  expiresAt: number;
  data: unknown;
};

const STUDIO_BOOTSTRAP_CACHE_KEY = "/api/studio/bootstrap";
const STUDIO_VOICES_CACHE_KEY = "/api/studio/voices";
const STUDIO_TTS_SETTINGS_CACHE_KEY = "/api/studio/tts/settings";
const STUDIO_TTS_VOICES_CACHE_KEY = "/api/studio/tts/voices";
const STUDIO_CODEX_MODELS_CACHE_KEY = "/api/studio/codex-models";
const STUDIO_SFX_CATALOG_CACHE_KEY = "/api/studio/sfx-catalog";
const STUDIO_MEME_LIBRARY_CACHE_KEY = "/api/studio/meme-library";
const STUDIO_MEDIA_ASSETS_CACHE_KEY = "/api/studio/media-assets";
const STUDIO_CATEGORY_METADATA_CACHE_KEY = "/api/publish/category-metadata";
const STUDIO_EMAIL_ADDRESS_BOOK_CACHE_KEY = "/api/studio/email-address-book";

const STUDIO_GET_CACHE_TTL_MS = {
  bootstrap: 20_000,
  voices: 30_000,
  ttsSettings: 15_000,
  ttsVoiceAssets: 15_000,
  codexModels: 30_000,
  sfxCatalog: 5 * 60_000,
  memeLibrary: 20_000,
  mediaAssets: 20_000,
  categoryMetadata: 15_000,
  emailAddressBook: 15_000,
} as const;

const studioGetCache = new Map<string, StudioGetCacheEntry>();
const studioGetInflight = new Map<string, Promise<unknown>>();

function canUseStudioBrowserCache(): boolean {
  return typeof window !== "undefined";
}

function toStudioGetCacheKey(input: RequestInfo | URL): string {
  if (typeof input === "string") return input;
  if (input instanceof URL) return input.toString();
  return String(input);
}

function readStudioGetCache<T>(cacheKey: string): T | null {
  if (!canUseStudioBrowserCache()) return null;
  const entry = studioGetCache.get(cacheKey);
  if (!entry) return null;
  if (entry.expiresAt <= Date.now()) {
    studioGetCache.delete(cacheKey);
    return null;
  }
  return entry.data as T;
}

function writeStudioGetCache<T>(cacheKey: string, data: T, ttlMs: number): T {
  if (!canUseStudioBrowserCache() || ttlMs <= 0) return data;
  studioGetCache.set(cacheKey, {
    expiresAt: Date.now() + ttlMs,
    data,
  });
  return data;
}

function invalidateStudioGetCache(prefixes: string[]): void {
  if (!canUseStudioBrowserCache()) return;
  const uniquePrefixes = Array.from(new Set(prefixes.map((prefix) => prefix.trim()).filter(Boolean)));
  if (uniquePrefixes.length <= 0) return;
  for (const cacheKey of Array.from(studioGetCache.keys())) {
    if (uniquePrefixes.some((prefix) => cacheKey.startsWith(prefix))) {
      studioGetCache.delete(cacheKey);
    }
  }
  for (const cacheKey of Array.from(studioGetInflight.keys())) {
    if (uniquePrefixes.some((prefix) => cacheKey.startsWith(prefix))) {
      studioGetInflight.delete(cacheKey);
    }
  }
}

async function fetchCachedStudioGet<T extends { ok: boolean }>(
  input: RequestInfo | URL,
  init: RequestInit | undefined,
  fallback: string,
  ttlMs: number
): Promise<T> {
  if (!canUseStudioBrowserCache() || ttlMs <= 0) {
    return requestApi<T>(input, init, fallback);
  }
  const cacheKey = toStudioGetCacheKey(input);
  const cached = readStudioGetCache<T>(cacheKey);
  if (cached) return cached;
  const inflight = studioGetInflight.get(cacheKey);
  if (inflight) return inflight as Promise<T>;
  const loader = requestApi<T>(input, init, fallback)
    .then((data) => writeStudioGetCache(cacheKey, data, ttlMs))
    .finally(() => {
      studioGetInflight.delete(cacheKey);
    });
  studioGetInflight.set(cacheKey, loader);
  return loader;
}

async function readJsonResponse<T>(response: Response): Promise<T> {
  const raw = await response.text();
  try {
    return JSON.parse(raw) as T;
  } catch {
    const isHtml = raw.trim().startsWith("<");
    const hint = isHtml
      ? "서버가 JSON 대신 HTML을 반환했습니다. 개발 서버 재시작 또는 API 라우트 오류 여부를 확인해 주세요."
      : "응답이 올바른 JSON 형식이 아닙니다.";
    throw new Error(`${hint} (status ${response.status})`);
  }
}

async function postParsed<T extends { ok: boolean }>(
  url: string,
  body: unknown,
  options?: { signal?: AbortSignal }
): Promise<ParsedApiResult<T>> {
  const serializedBody = typeof body === "string" ? body : JSON.stringify(body);
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: serializedBody,
    signal: options?.signal,
  });
  const data = await readJsonResponse<T | ApiErrorResponse>(response);
  return {
    responseOk: response.ok,
    data,
  };
}

