export async function disconnectStudioCodexOauth(): Promise<boolean> {
  const response = await fetch("/api/auth/codex/disconnect", { method: "POST" });
  if (response.ok) {
    invalidateStudioGetCache([STUDIO_BOOTSTRAP_CACHE_KEY]);
  }
  return response.ok;
}

