export async function fetchStudioMemeLibrary(input?: {
  limit?: number;
  query?: string;
  tag?: string;
  emotionTag?: string;
  mediaKind?: "all" | "image" | "motion";
}): Promise<StudioMemeLibraryResponse> {
  const params = new URLSearchParams();
  if (typeof input?.limit === "number" && Number.isFinite(input.limit)) params.set("limit", String(Math.floor(input.limit)));
  if (input?.query?.trim()) params.set("query", input.query.trim());
  if (input?.tag?.trim()) params.set("tag", input.tag.trim());
  if (input?.emotionTag?.trim()) params.set("emotionTag", input.emotionTag.trim());
  if (input?.mediaKind) params.set("mediaKind", input.mediaKind);
  const suffix = params.toString();
  const url = `${STUDIO_MEME_LIBRARY_CACHE_KEY}${suffix ? `?${suffix}` : ""}`;
  return fetchCachedStudioGet<StudioMemeLibraryResponse>(
    url,
    { cache: "no-store" },
    "밈 라이브러리를 불러오지 못했습니다.",
    STUDIO_GET_CACHE_TTL_MS.memeLibrary
  );
}

