function buildStudioPreparePayload(input: {
  parsed: Record<string, unknown>;
  publishCategory: PublishCategory;
  projectProfileSnapshot?: StudioProjectProfileSnapshot | null;
  fixedCharacterProfileId?: string;
  imageSource: ImageSource;
  crawlMode: CrawlMode;
  codexModel?: string;
  debugImageSearch?: boolean;
}): Record<string, unknown> {
  const {
    imageStylePrompt,
    characterProfiles,
    fixedCharacterProfileId: _parsedFixedCharacterProfileId,
    ...modeNeutralParsed
  } = input.parsed;
  const fixedCharacterProfileId = String(input.fixedCharacterProfileId || "").trim() || undefined;
  const aiImageState = isStudioGeneratedImageSource(input.imageSource)
    ? fixedCharacterProfileId
      ? { fixedCharacterProfileId }
      : isStudioAutoGeneratedImageSource(input.imageSource)
        ? { imageStylePrompt, characterProfiles }
        : { imageStylePrompt }
    : {};
  return {
    ...modeNeutralParsed,
    ...aiImageState,
    codexModel: input.codexModel || undefined,
    videoMode: "segments",
    ttsProvider: "typecast",
    publishCategory: input.publishCategory,
    projectProfileSnapshot: input.projectProfileSnapshot || undefined,
    imagePolicy: {
      source: input.imageSource,
      allowGenerated: isStudioGeneratedImageSource(input.imageSource),
      fallback: "body-only",
    },
    crawlMode: input.crawlMode,
    debugImageSearch: input.debugImageSearch || undefined,
  };
}

function sanitizeSlidesForPrepareResolve(input: Record<string, unknown>): Record<string, unknown> {
  const slides = Array.isArray(input.slides) ? input.slides : [];
  return {
    ...input,
    slides: slides.map((slide) => {
      if (!slide || typeof slide !== "object") return slide as Record<string, unknown>;
      const row = slide as Record<string, unknown>;
      const {
        title: _title,
        layout: _layout,
        ...rest
      } = row;
      return rest;
    }),
  };
}

export async function requestStudioPrepare(input: {
  parsed: Record<string, unknown>;
  publishCategory: PublishCategory;
  projectProfileSnapshot?: StudioProjectProfileSnapshot | null;
  fixedCharacterProfileId?: string;
  imageSource: ImageSource;
  crawlMode: CrawlMode;
  codexModel?: string;
  debugImageSearch?: boolean;
}): Promise<ParsedApiResult<StudioPrepareResponse>> {
  const payload = buildStudioPreparePayload(input);
  const serializeStartedAt =
    typeof performance !== "undefined" && Number.isFinite(performance.now()) ? performance.now() : Date.now();
  const payloadSlides = payload.slides;
  const slideCount = Array.isArray(payloadSlides) ? payloadSlides.length : 0;
  console.info(`[studio-prepare:client] serialize_start slides=${slideCount}`);
  const bodyText = JSON.stringify(payload);
  const serializeEndedAt =
    typeof performance !== "undefined" && Number.isFinite(performance.now()) ? performance.now() : Date.now();
  console.info(
    `[studio-prepare:client] slides=${slideCount} bytes=${bodyText.length} stringify_ms=${Math.max(0, Math.round(serializeEndedAt - serializeStartedAt))}`
  );
  return postParsed<StudioPrepareResponse>("/api/studio/prepare", bodyText);
}

